int format_cert_identifier(char* id_buffer, size_t buffer_size, const char* subject, const char* issuer, const char* serial) {
    if (id_buffer == NULL || buffer_size == 0) {
        return -1;
    }

    if (subject == NULL || issuer == NULL || serial == NULL) {
        return -2;
    }

    // Initialize the buffer
    id_buffer[0] = '\0';

    // Calculate the required length to check for overflow
    size_t subject_len = strlen(subject);
    size_t issuer_len = strlen(issuer);
    size_t serial_len = strlen(serial);
    size_t total_len = subject_len + issuer_len + serial_len + 6; // +6 for "Subject:" + "Issuer:" + "Serial:" + 3 commas + null terminator

    if (total_len > buffer_size) {
        return -3; // Buffer too small
    }

    // Start building the identifier string
    if (strncat(id_buffer, "Subject:", buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    if (strncat(id_buffer, subject, buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    if (strncat(id_buffer, ",Issuer:", buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    if (strncat(id_buffer, issuer, buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    if (strncat(id_buffer, ",Serial:", buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    if (strncat(id_buffer, serial, buffer_size - strlen(id_buffer) - 1) == NULL) {
        return -4;
    }

    return 0; // Success
}
